roommate_emails = {normalize_identity(contact['email']) for contact in roommates if normalize_identity(contact['email'])}
roommate_names = {normalize_identity(' '.join([contact['first_name'], contact['last_name']])) for contact in roommates if normalize_identity(' '.join([contact['first_name'], contact['last_name']]))}
def party_is_roommate(party):
    party_email = normalize_identity(party['email'])
    party_name = normalize_identity(party['name'])
    return (bool(party_email) and party_email in roommate_emails) or (bool(party_name) and party_name in roommate_names)
